// HP is the recorded resolved health (10R-damage). Allowance is an explicit
// fixture input resolved from the neutral Infantry creation/movement handoff;
// the production combat model does not compute it. Mode remains provenance.
// Original promotion weights are participant-ordered; these named model
// expectations normalize them to winner/loser order using the recorded winner.
struct Input { std::array< int32_t, 2 > reactors, health, morale; int32_t spent, allowance; uint32_t shared, crt; bool alternate_mode; };
struct Round { std::array< int32_t, 2 > health_before, draws; };
struct Draw { int phase; uint32_t before, after; uint16_t raw; };
struct Case {
	const char* id; Input input;
	std::array< int32_t, 2 > strengths, widths, health_after, weights;
	bool attacker_won, admitted; int32_t stored_before, stored_after, survivor_spent;
	size_t first_round, round_count, first_draw, draw_count;
	int selected_index, secondary_index, continuation_index, core_return, wrapper_return;
	std::array< bool, 2 > present; uint32_t shared_after, crt_after;
};

